mapper.select:
SELECT

FROM inc_institute ins
WHERE delete_state = 0

  AND parent_id = #{parentId,jdbcType=VARCHAR}
  AND third_id = #{thirdId,jdbcType=VARCHAR}


  AND institute_name = #{instituteName,jdbcType=VARCHAR}


  AND id != #{id,jdbcType=VARCHAR}

LIMIT 1
